-- Native json type: invalid documents are rejected automatically
CREATE TABLE dbo.Orders (
    OrderId INT IDENTITY PRIMARY KEY,
    Doc JSON NOT NULL
);

INSERT INTO dbo.Orders (Doc)
VALUES ('{"customer":"Adeel","items":[{"sku":"A1","qty":2}]}');

-- SQL Server 2025 JSON index (preview)
ALTER DATABASE SCOPED CONFIGURATION SET PREVIEW_FEATURES = ON;
CREATE JSON INDEX JX_Orders_Doc ON dbo.Orders (Doc) FOR ('$.customer');

-- Classic pattern: computed column + B-tree
ALTER TABLE dbo.Orders
    ADD CustomerName AS JSON_VALUE(Doc, '$.customer');
CREATE INDEX IX_Orders_Customer ON dbo.Orders (CustomerName);
